import json
from pathlib import Path
P=Path(__file__).resolve().parents[1]
sectors={s['id']:s for f in (P/'seeds').glob('*.json') for s in json.load(open(f))}
activities=[x for x in json.load(open(P/'company_rules/observed_activities.json')) if int(x['okved'][:2])>=70]
rows={x['okved']:{'okved':x['okved'],'activity':x['activity'],'mappings':[],'unmapped_reason':None} for x in activities}
def add(codes,sector,objects,relation,reason):
 for code in codes.split('|'):
  assert code in rows,code
  obs=[o['name'] for o in sectors[sector]['objects']]
  chosen=[obs[i] for i in objects] if all(isinstance(i,int) for i in objects) else objects
  assert set(chosen)<=set(obs),(sector,chosen)
  rows[code]['mappings'].append(dict(sector_id=sector,objects=chosen,relation=relation,reason=reason,signal_names=[]))
def gap(codes,reason):
 for code in codes.split('|'):rows[code]['unmapped_reason']=reason
